changeSet.sql:
-- Payroll permissions (hrm-service, schema `payroll`). Numbered 021 because 020 is -- reserved for identity.department (comfy-payroll-architecture.md ARCH-02). INSERT INTO identity.permission (permission_code, scope, description) VALUES ('HR_RECORD_READ', 'BUSINESS', 'read individual pay, contracts, bank details, payroll audit log'), ('HR_RECORD_WRITE', 'BUSINESS', 'write employee profile, contracts, allowances, leave quotas'), ('PAYROLL_CONFIG_WRITE', 'BUSINESS', 'write payroll config and payroll reference data'), ('PAYROLL_PROCESS', 'BUSINESS', 'periods, roster, timesheet, manual items, payroll runs'), ('PAYROLL_APPROVE', 'BUSINESS', 'lock, unlock, mark paid, acknowledge warnings'), ('PAYSLIP_ISSUE', 'BUSINESS', 'generate and send payslips'), ('PAYROLL_REPORT_READ', 'BUSINESS', 'business-wide aggregate labour-cost reports'), ('TIMESHEET_READ', 'BRANCH', 'view roster and timesheet at a branch'), ('TIMESHEET_EDIT', 'BRANCH', 'edit roster and timesheet at a branch'), ('LABOR_COST_READ', 'BRANCH', 'branch aggregate labour cost');
GRANT SELECT ON identity.permission TO svc_hrm; GRANT SELECT ON identity.position_permission TO svc_hrm; GRANT SELECT ON identity.staff_branch_permission TO svc_hrm; GRANT SELECT ON identity.staff_business_permission TO svc_hrm; GRANT SELECT ON identity.permission_revision TO svc_hrm;
-- Like-for-like seeding, so DEC-05 ("only admin and HR see individual pay") holds on day one. -- The existing grant triggers audit these rows and bump permission_revision.
-- De-facto admins (live PERMISSION_GRANT) receive the 7 business payroll permissions. INSERT INTO identity.staff_business_permission (staff_id, permission_code, business_id) SELECT g.staff_id, p.permission_code, g.business_id FROM identity.staff_business_permission g CROSS JOIN (VALUES ('HR_RECORD_READ'), ('HR_RECORD_WRITE'), ('PAYROLL_CONFIG_WRITE'), ('PAYROLL_PROCESS'), ('PAYROLL_APPROVE'), ('PAYSLIP_ISSUE'), ('PAYROLL_REPORT_READ')) AS p(permission_code) WHERE g.permission_code = 'PERMISSION_GRANT' AND g.revoked_at IS NULL;
-- De-facto branch managers (live CLOSE_REVIEW at a branch, direct or through a position) -- receive the three branch payroll permissions at that branch - never HR_RECORD_READ. INSERT INTO identity.staff_branch_permission (staff_id, branch_id, permission_code, business_id) SELECT r.staff_id, r.branch_id, p.permission_code, r.business_id FROM ( SELECT staff_id, branch_id, business_id FROM identity.staff_branch_permission WHERE permission_code = 'CLOSE_REVIEW' AND revoked_at IS NULL UNION SELECT a.staff_id, a.branch_id, a.business_id FROM identity.staff_branch_position a JOIN identity.position_permission pp ON pp.position_id = a.position_id AND pp.business_id = a.business_id WHERE pp.permission_code = 'CLOSE_REVIEW' AND pp.revoked_at IS NULL AND a.revoked_at IS NULL ) r CROSS JOIN (VALUES ('TIMESHEET_READ'), ('TIMESHEET_EDIT'), ('LABOR_COST_READ')) AS p(permission_code);
